extern "C" int sprintf(char *, const char *, ...);

class stringx
{
  char *chars;
  void *my_buf;
public:
  stringx(const char *, int = -1);
  ~stringx();
  const char *c_str() const { return chars; }
};

template<class T> class singleton_ptr
{
  T *p;
public:
  operator T *() const { return p; }
};

class input_mgr
{
  static singleton_ptr<input_mgr> instance;
public:
  static input_mgr *inst() { return instance; }
  float get_control_state(int, int) const;
};

class entity
{
public:
  void *play_anim(int, const stringx &, float, unsigned short = 0, short = -1);
};

class generic_anim_animal
{
  stringx my_base_name;
  int cur_state, cur_anim;
  bool dummy;
  bool left_down, right_down;
  char pad[5];
  int generic_anims[2];
  int generic_anim_state;
  entity *my_entity;

  static const char *generic_anim_names[];
  enum { AA_IDLE, AA_DIVE, AA_SPAWN };
public:
  void switch_anims();
};

void generic_anim_animal::switch_anims ()
{
	if (!dummy)
		return;

	input_mgr* inputmgr = input_mgr::inst();

	if (inputmgr->get_control_state(1, 188) == 1.0f)
	{
		if (!left_down)
		{
			left_down = true;
			cur_anim--;

			if (cur_anim <= 0)
			{
				cur_state--;

				if (cur_state < 0)
					cur_state = AA_DIVE;

				cur_anim = generic_anims[cur_state];
			}

			char anim[256];
			sprintf (anim, "%s_%s_%d", my_base_name.c_str(), generic_anim_names[cur_state], cur_anim);
	    my_entity->play_anim (0, anim, 0.3f, 0x0a04);
		}
	}
	else
	{
		left_down = false;
	}

	if (inputmgr->get_control_state(1, 191) == 1.0f)
	{
		if (!right_down)
		{
			right_down = true;
			cur_anim++;

			if (cur_anim > generic_anims[cur_state])
			{
				cur_anim = 1;
				cur_state++;
				if (cur_state > AA_DIVE)
					cur_state = 0;
			}

			char anim[256];
			sprintf (anim, "%s_%s_%d", my_base_name.c_str(), generic_anim_names[cur_state], cur_anim);
			my_entity->play_anim (0, anim, 0.3f, 0x0a04);
		}
	}
	else
	{
		right_down = false;
	}
}
